const raw = $input.first().json.body;
if (!raw || typeof raw !== 'object') {
  throw new Error('O corpo da requisição não chegou como XML. Envie com o cabeçalho Content-Type: application/xml.');
}

// Passa todas as chaves para minúsculas, para não depender de como o n8n converteu o XML
const lower = o => Array.isArray(o) ? o.map(lower)
  : (o && typeof o === 'object')
    ? Object.fromEntries(Object.entries(o).map(([k, v]) => [k.toLowerCase(), lower(v)]))
    : o;

const body = lower(raw);
const nfe = body?.nfeproc?.nfe ?? body?.nfe;
const inf = nfe?.infnfe;
if (!inf) throw new Error('XML sem infNFe. Chaves recebidas: ' + Object.keys(body || {}).join(', '));

const attr = (o, k) => o?.$?.[k] ?? o?.[`@_${k}`] ?? o?.[k];
const arr = x => (x == null ? [] : Array.isArray(x) ? x : [x]);
const num = v => (v == null || v === '' || isNaN(Number(v)) ? null : Number(v));
// PIS/COFINS/ICMS têm um subgrupo (pisaliq, pisnt, icms00, icmssn500...) que contém CST e valores
const grupo = g => {
  if (!g || typeof g !== 'object') return {};
  const k = Object.keys(g).find(k => k !== '$' && typeof g[k] === 'object');
  return k ? g[k] : {};
};

const chave = String(attr(inf, 'id') || '').replace(/^NFe/i, '');
if (!/^\d{44}$/.test(chave)) throw new Error('Chave de acesso inválida: "' + chave + '"');

// Só aceita nota autorizada (100 = autorizada, 150 = autorizada fora de prazo)
const cstat = body?.nfeproc?.protnfe?.infprot?.cstat ?? null;
if (cstat && !['100', '150'].includes(String(cstat))) {
  throw new Error('NF-e não autorizada (cStat ' + cstat + '). Nota ignorada.');
}

const itens = arr(inf.det).map((d, i) => {
  const p = d.prod || {};
  const pis = grupo(d.imposto?.pis);
  const cof = grupo(d.imposto?.cofins);
  const icms = grupo(d.imposto?.icms);
  return {
    item_numero: Number(attr(d, 'nitem')) || i + 1,
    produto_original: p.xprod ?? null,
    ncm: String(p.ncm ?? ''),
    cfop: p.cfop ?? null,
    valor_item: num(p.vprod),
    icms_cst: icms.csosn ?? icms.cst ?? null,
    icms_valor: num(icms.vicms),
    pis_cst: pis.cst ?? null,
    pis_bc: num(pis.vbc),
    pis_aliquota: num(pis.ppis),
    pis_valor: num(pis.vpis),
    cofins_cst: cof.cst ?? null,
    cofins_bc: num(cof.vbc),
    cofins_aliquota: num(cof.pcofins),
    cofins_valor: num(cof.vcofins)
  };
});

return [{
  json: {
    chave_acesso: chave,
    cnpj_emitente: inf.emit?.cnpj ?? null,
    cnpj_destinatario: inf.dest?.cnpj ?? null,
    numero: inf.ide?.nnf ? String(inf.ide.nnf) : null,
    crt: inf.emit?.crt != null ? String(inf.emit.crt) : null,
    tp_amb: inf.ide?.tpamb != null ? String(inf.ide.tpamb) : null,
    data_emissao: String(inf.ide?.dhemi ?? inf.ide?.demi ?? '').slice(0, 10) || null,
    xml_bruto: JSON.stringify(raw),
    itens
  }
}];

parameters.query:
SELECT
  COALESCE((SELECT json_agg(r ORDER BY length(r.ncm_prefixo) DESC) FROM regra_fiscal r), '[]'::json) AS regras,
  COALESCE((SELECT json_agg(c) FROM cliente c), '[]'::json) AS clientes;

