const nota = $('Extrair NF-e').first().json;
const { regras = [], clientes = [] } = $input.first().json;

// Quem é o cliente nesta nota?
const cEmit = clientes.find(c => c.cnpj === nota.cnpj_emitente);
const cDest = clientes.find(c => c.cnpj === nota.cnpj_destinatario);
const cliente = cEmit ?? cDest;
if (!cliente) {
  throw new Error('Nenhum CNPJ desta nota está cadastrado como cliente (emitente ' + nota.cnpj_emitente +
    ', destinatário ' + nota.cnpj_destinatario + '). Rode ./cliente_novo.sh antes de enviar as notas.');
}
const papel = cEmit ? 'EMITENTE' : 'DESTINATARIO';
const regime = cliente.regime;
const simples = regime === 'SIMPLES';
const atividade = cliente.atividade || 'COMERCIO';
const homologacao = String(nota.tp_amb) === '2';

const avisos = [];
if (homologacao) avisos.push('Nota de HOMOLOGAÇÃO (sem valor fiscal): não deve ser usada como achado real.');
if (papel === 'EMITENTE' && (String(nota.crt) === '1' || String(nota.crt) === '2') !== simples)
  avisos.push('O regime cadastrado do cliente (' + regime + ') não combina com o CRT da nota (' + nota.crt + '). Confira o cadastro.');

const n = v => (v == null ? 0 : Number(v));
const r2 = v => Math.round(v * 100 + 1e-6) / 100;
const TRIBUTADO = ['01', '02'];
const NAO_TRIBUTADO = ['04', '05', '06', '07', '08', '09'];
const PRIORIDADE = ['POSSIVEL_PAGAMENTO_INDEVIDO', 'DIVERGENTE_REGRA', 'TESE_ICMS_BASE',
                    'OPORTUNIDADE_SIMPLES', 'CALCULO_DIVERGENTE', 'INCONSISTENCIA'];

const vigente = r =>
  (!r.vigencia_inicio || r.vigencia_inicio <= nota.data_emissao) &&
  (!r.vigencia_fim || r.vigencia_fim >= nota.data_emissao);

const semRegra = new Map();

const itens = nota.itens.map(it => {
  // Nota de COMPRA do cliente: análise de créditos ainda não implementada
  if (papel !== 'EMITENTE') {
    return { ...it, achado: 'FORA_ESCOPO', camada: null,
      detalhe_regra: 'Nota de compra do cliente: a análise de créditos de PIS/COFINS/ICMS ainda não está implementada.',
      aliquota_esperada: null, base_legal: null, valor_recuperavel: null };
  }

  const achados = [];
  const add = (achado, camada, detalhe, valor = null) => achados.push({ achado, camada, detalhe, valor });
  const pago = n(it.pis_valor) + n(it.cofins_valor);

  // ===== CAMADA 1: verificações universais (só lendo o XML) =====
  if (!simples) {
    const tributos = [
      { nome: 'PIS', cst: it.pis_cst, bc: it.pis_bc, aliq: it.pis_aliquota, valor: it.pis_valor },
      { nome: 'COFINS', cst: it.cofins_cst, bc: it.cofins_bc, aliq: it.cofins_aliquota, valor: it.cofins_valor }
    ];
    let teseIcms = 0;
    for (const t of tributos) {
      if (TRIBUTADO.includes(t.cst) && n(t.valor) === 0)
        add('INCONSISTENCIA', 1, `${t.nome}: CST ${t.cst} (tributável) com valor zerado.`);
      if (NAO_TRIBUTADO.includes(t.cst) && n(t.valor) > 0)
        add('POSSIVEL_PAGAMENTO_INDEVIDO', 1, `${t.nome}: CST ${t.cst} (sem tributação) mas com valor destacado de ${t.valor}.`, n(t.valor));
      if (t.aliq != null && t.bc != null && t.valor != null && Math.abs(t.bc * t.aliq / 100 - t.valor) > 0.02)
        add('CALCULO_DIVERGENTE', 1, `${t.nome}: valor ${t.valor} não bate com base ${t.bc} x alíquota ${t.aliq}%.`);
      // Tese: ICMS dentro da base do PIS/COFINS (STF, RE 574.706 / Tema 69)
      if (TRIBUTADO.includes(t.cst) && n(it.icms_valor) > 0 && t.bc != null && t.aliq != null &&
          it.valor_item != null && t.bc >= it.valor_item - 0.02)
        teseIcms += n(it.icms_valor) * t.aliq / 100;
    }
    if (teseIcms > 0)
      add('TESE_ICMS_BASE', 1,
        `ICMS destacado de ${n(it.icms_valor)} parece não ter sido excluído da base de PIS/COFINS (base ${it.pis_bc} = valor do item). Tese: exclusão do ICMS da base. Validar com tributarista.`,
        r2(teseIcms));
  } else {
    // Cliente do Simples Nacional: ICMS-ST já pago na compra (CSOSN 500)
    if (String(it.icms_cst) === '500')
      add('OPORTUNIDADE_SIMPLES', 1,
        'Venda com ICMS-ST já recolhido anteriormente (CSOSN 500): verificar se a receita foi segregada (sem a parcela de ICMS) no PGDAS-D.');
  }

  // ===== CAMADA 2: regra por NCM, considerando o regime do cliente =====
  const regra = regras.find(r =>
    r.tributo === 'PIS_COFINS' &&
    it.ncm.startsWith(r.ncm_prefixo) &&
    (!r.regime || r.regime === 'TODOS' || r.regime === regime) &&
    vigente(r)
  );

  if (regra) {
    const aviso = regra.validada ? '' : ' (regra ainda NÃO validada por contador)';
    const trat = regra.tratamento;
    const csts = (regra.cst_esperados || '').split(',').map(s => s.trim()).filter(Boolean);
    const aplica = trat === 'ALIQ_ZERO' || (trat === 'MONOFASICO' && atividade === 'COMERCIO');

    if (aplica && !simples && pago > 0)
      add('DIVERGENTE_REGRA', 2,
        `NCM ${it.ncm}: tratamento ${trat}, mas houve PIS/COFINS de ${pago.toFixed(2)} na nota.${aviso}`, r2(pago));
    if (aplica && !simples && csts.length && !csts.includes(String(it.pis_cst)))
      add('DIVERGENTE_REGRA', 2, `NCM ${it.ncm}: CST ${it.pis_cst} fora do esperado (${csts.join(', ')}).${aviso}`);
    if (aplica && simples)
      add('OPORTUNIDADE_SIMPLES', 2,
        `NCM ${it.ncm} com tratamento ${trat}: cliente do Simples deve segregar essa receita (sem PIS/COFINS) no PGDAS-D. Conferir.${aviso}`);
  } else if (!homologacao) {
    semRegra.set(it.ncm, it.produto_original);
  }

  const achado = PRIORIDADE.find(p => achados.some(a => a.achado === p)) ?? (regra ? 'CONFORME' : 'SEM_REGRA');
  const principal = achados.find(a => a.achado === achado);
  // Soma só os valores do achado principal (PIS + COFINS), sem misturar tipos diferentes (evita contar duas vezes)
  const vals = achados.filter(a => a.achado === achado && a.valor != null).map(a => a.valor);
  const valorRecuperavel = vals.length ? r2(vals.reduce((s, v) => s + v, 0)) : null;

  return {
    ...it,
    achado,
    camada: principal?.camada ?? (regra ? 2 : null),
    detalhe_regra: achados.map(a => a.detalhe).join(' | ')
      || (regra ? 'Sem divergência nas regras aplicáveis.' : 'Nenhuma regra cadastrada para este NCM.'),
    aliquota_esperada: regra?.aliquota_esperada ?? null,
    base_legal: regra?.base_legal ?? (achado === 'TESE_ICMS_BASE' ? 'STF, RE 574.706 (Tema 69) — A VALIDAR' : null),
    valor_recuperavel: valorRecuperavel
  };
});

return [{
  json: {
    ...nota,
    homologacao,
    avisos,
    cliente_cnpj: cliente.cnpj,
    papel_cliente: papel,
    ncms_sem_regra: [...semRegra].filter(([ncm]) => ncm).map(([ncm, descricao]) => ({ ncm, descricao })),
    itens
  }
}];

const nota = $('Comparar Regras').first().json;
const json = $input.first().json;
let ia = [];

// Lê a resposta da IA em qualquer formato. Se falhar, os achados das regras continuam valendo.
try {
  if (Array.isArray(json)) ia = json;
  else if (Array.isArray(json.text)) ia = json.text;
  else if (Array.isArray(json.output)) ia = json.output;
  else {
    let txt = '';
    if (typeof json.text === 'string') txt = json.text;
    else if (typeof json.content === 'string') txt = json.content;
    else if (json.content?.parts?.[0]?.text) txt = json.content.parts[0].text;
    if (txt) ia = JSON.parse(txt.replace(/```json/gi, '').replace(/```/g, '').trim());
  }
  if (!Array.isArray(ia)) ia = [];
} catch (e) {
  ia = [];
}

const MODELO = 'gemini-3.5-flash-lite';
const prefixo = nota.homologacao ? '[NOTA DE HOMOLOGAÇÃO] ' : '';

const itens = nota.itens.map(it => {
  const r = ia.find(a => Number(a.item_numero) === it.item_numero);
  return {
    item_numero: it.item_numero,
    produto_original: it.produto_original ?? '(sem descrição)',
    ncm_analisado: it.ncm,
    status_tributario: it.achado,
    alerta_gerado: prefixo + (r?.alerta_auditoria ?? it.detalhe_regra),
    cst_declarado: it.pis_cst,
    aliquota_declarada: it.pis_aliquota,
    aliquota_esperada: it.aliquota_esperada,
    valor_recuperavel_estimado: it.valor_recuperavel,
    base_legal: it.base_legal,
    achado: it.achado,
    camada: it.camada,
    detalhe_regra: it.detalhe_regra,
    resposta_ia_bruta: r ?? null,
    modelo_ia: r ? MODELO : null
  };
});

return [{
  json: {
    chave_acesso: nota.chave_acesso,
    cnpj_emitente: nota.cnpj_emitente,
    cnpj_destinatario: nota.cnpj_destinatario,
    numero: nota.numero,
    data_emissao: nota.data_emissao,
    xml_bruto: nota.xml_bruto,
    crt: nota.crt,
    tp_amb: nota.tp_amb,
    cliente_cnpj: nota.cliente_cnpj,
    papel_cliente: nota.papel_cliente,
    homologacao: nota.homologacao,
    avisos: nota.avisos,
    ncms_sem_regra: nota.ncms_sem_regra,
    itens
  }
}];

const nota = $('Processador de Lote').first().json;
const db = $input.first().json;
const por_achado = {};
let total = 0;
for (const i of nota.itens) {
  por_achado[i.achado] = (por_achado[i.achado] || 0) + 1;
  total += Number(i.valor_recuperavel_estimado) || 0;
}
return [{
  json: {
    status: 'ok',
    chave_acesso: nota.chave_acesso,
    cliente_cnpj: nota.cliente_cnpj,
    papel_cliente: nota.papel_cliente,
    homologacao: nota.homologacao,
    itens_na_nota: nota.itens.length,
    itens_gravados: Number(db.itens_gravados ?? 0),
    achados: por_achado,
    valor_estimado_total: Math.round(total * 100) / 100,
    ncms_sem_regra: (nota.ncms_sem_regra || []).length,
    avisos: nota.avisos
  }
}];

const json = $input.first().json;
let ia = [];
try {
  if (Array.isArray(json)) ia = json;
  else if (Array.isArray(json.text)) ia = json.text;
  else if (Array.isArray(json.output)) ia = json.output;
  else {
    let txt = '';
    if (typeof json.text === 'string') txt = json.text;
    else if (typeof json.content === 'string') txt = json.content;
    else if (json.content?.parts?.[0]?.text) txt = json.content.parts[0].text;
    if (txt) ia = JSON.parse(txt.replace(/```json/gi, '').replace(/```/g, '').trim());
  }
  if (!Array.isArray(ia)) ia = [];
} catch (e) {
  ia = [];
}
const pedidos = new Set($('Montar lote').first().json.ncms.map(x => x.ncm));
const validos = ia.filter(s => s && pedidos.has(String(s.ncm)));
// Se a IA não devolveu nada utilizável, não devolve itens: o fluxo para e os NCMs continuam PENDENTES.
return validos.map(s => ({ json: { ncm: String(s.ncm), resposta: s } }));
